        n=len(v)
        if n==0: return True
        pmin=[0]*n; m=10**9
        for i in range(n):
            m=min(m,v[i]); pmin[i]=m
        smax=[0]*n; M=-1
        for i in range(n-1,-1,-1):
            M=max(M,v[i]); smax[i]=M
        for i in range(n):
            if (i>0 and pmin[i-1]<v[i]) or (i<n-1 and smax[i+1]>v[i]): continue
            return False
        return True
    pts=sorted(zip(X,Y))
    ans = 1 if ok(0,N+1,0,N+1) else 0
    dp={}
    for bx,by in pts:
        val=1 if ok(0,bx,by,N+1) else 0
