            if ax>=bx: break
            if ay>by and dp[ax]:
                if ok(ax,bx,by,ay):
                    val=(val+dp[ax])%MOD
        dp[bx]=val
        if ok(bx,N+1,0,by):
            ans=(ans+val)%MOD
