from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byb = [[] for _ in range(n+1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            byb[b].append(a)
        M1 = [0]*(n+1)
        diff = [0]*(n+1)
        m1 = m2 = 0
        for r in range(1, n+1):
            for a in byb[r]:
                if a > m1:
                    m2, m1 = m1, a
                elif a > m2:
                    m2 = a
            M1[r] = m1
            diff[r] = m1 - m2
        base = sum(r - M1[r] for r in range(1, n+1))
        P = [0]*(n+1)
        for r in range(1, n+1):
            P[r] = P[r-1] + diff[r]
        first = {}
        last = {}
        for r in range(1, n+1):
            v = M1[r]
            if v == 0:
                continue
            if v not in first:
                first[v] = r
            last[v] = r
        best = 0
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if a not in first:
                continue
            lo = max(b, first[a])
            hi = last[a]
            if lo <= hi:
                g = P[hi] - P[lo-1]
                if g > best:
                    best = g
        return base + best

