from math import factorial
import sys
def f_exact(lam):
    lam=[x for x in lam if x>0]
    n=sum(lam)
    if n==0: return 1
    conj=[sum(1 for r in lam if r>j) for j in range(lam[0])]
    h=1
    for i,r in enumerate(lam):
        for j in range(r):
            h*=(r-j-1)+(conj[j]-i-1)+1
    return factorial(n)//h
def solve(A,B,M):
    # mu = (A-1, A-1, m_3..m_B), m non-increasing length B-2, values in [0,A-1]
    total=0
    def gen(k,maxv):
        if k==0:
            yield ()
            return
        for v in range(maxv,-1,-1):
            for rest in gen(k-1,v):
                yield (v,)+rest
    for seq in gen(B-2,A-1):
        mu=[A-1,A-1]+list(seq)
        nu=[A-x for x in reversed(seq)]
        total+= f_exact(mu)*f_exact(nu)
    return total%M
