import sys, heapq
def solve_case(n, m, boxes):
    boxes.sort(key=lambda x: -x[0])
    V = [b[0] for b in boxes]; P = [b[1] for b in boxes]
    d = [V[i]-P[i] for i in range(n)]
    suf_pos = [0]*(n+1); suf_max = [-(1<<62)]*(n+1)
    for i in range(n-1, -1, -1):
        suf_pos[i] = suf_pos[i+1] + (d[i] if d[i] > 0 else 0)
        suf_max[i] = max(suf_max[i+1], d[i])
    def R(i):
        return suf_pos[i] if suf_max[i] > 0 else suf_max[i]
    best = 0
    if m == 1:
        return max(0, R(0))
    k = m-2
    h = []; s = 0
    for p in range(n-1):
        if len(h) == k:
            val = (m-1) - P[p] - s + R(p+1)
            if val > best: best = val
        heapq.heappush(h, -P[p]); s += P[p]
        if len(h) > k:
            x = -heapq.heappop(h); s -= x
    return best
def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0]); pos = 1
    out = []
    for _ in range(t):
        n = int(data[pos]); m = int(data[pos+1]); pos += 2
        boxes = []
        for i in range(n):
            boxes.append((int(data[pos]), int(data[pos+1]))); pos += 2
        out.append(str(solve_case(n, m, boxes)))
    sys.stdout.write("\n".join(out) + "\n")
