class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        def steps(x):
            t = 0
            while x != 1:
                x = bin(x).count('1')
                t += 1
            return t

        C = [[0] * (L + 2) for _ in range(L + 2)]
        for i in range(L + 2):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        cnt = [0] * (L + 1)
        ones = 0
        for i in range(L):
            if s[i] == '1':
                rem = L - i - 1
                for c in range(ones, min(L, ones + rem) + 1):
                    cnt[c] = (cnt[c] + C[rem][c - ones]) % MOD
                ones += 1

        ans = 0
        for c in range(1, L + 1):
            if steps(c) <= k - 1:
                ans = (ans + cnt[c]) % MOD
        return ans

