import sys
def main():
    d=sys.stdin.read().split()
    n,m=int(d[0]),int(d[1])
    adj=[0]*n
    for i in range(m):
        u=int(d[2+2*i])-1; v=int(d[3+2*i])-1
        adj[u]|=1<<v; adj[v]|=1<<u
    R=[a for a in adj if a]
    r=0
    pc=[]
    for c in range(n):
        sel=-1
        for i in range(r,len(R)):
            if R[i]>>c&1:
                sel=i;break
        if sel<0: continue
        R[r],R[sel]=R[sel],R[r]
        for i in range(len(R)):
            if i!=r and R[i]>>c&1:
                R[i]^=R[r]
        pc.append(c)
        r+=1
    pset=set(pc)
    free=[c for c in range(n) if c not in pset]
    basis=[]
    for f in free:
        vec=1<<f
        for i,p in enumerate(pc):
            if R[i]>>f&1:
                vec|=1<<p
        basis.append(vec)
    X=[0]*n
    for j,b in enumerate(basis):
        for v in range(n):
            if b>>v&1:
                X[v]|=1<<j
    if any(x==0 for x in X):
        print("No")
    else:
        print("Yes")
        print(*X)
