from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        def f(o, e, np):
            L = o + e
            if L == 0:
                return 1
            need_np = (L + 1) // 2
            need_other = L // 2
            if np == 1:
                if o != need_np or e != need_other:
                    return 0
            else:
                if e != need_np or o != need_other:
                    return 0
            return factorial(o) * factorial(e)

        odd = (n + 1) // 2
        even = n // 2
        total = f(odd, even, 1) + f(odd, even, 0)
        if k > total:
            return []
        S = set(range(1, n + 1))
        last = None
        res = []
        for _ in range(n):
            chosen = None
            for v in sorted(S):
                p = v % 2
                if last is not None and p == last:
                    continue
                o = sum(1 for x in S if x % 2 == 1) - (1 if p == 1 else 0)
                e = sum(1 for x in S if x % 2 == 0) - (1 if p == 0 else 0)
                cnt = f(o, e, 1 - p)
                if k <= cnt:
                    chosen = v
                    break
                k -= cnt
            res.append(chosen)
            S.remove(chosen)
            last = chosen % 2
        return res

