class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n
        f = [1] * (N + 2)
        for i in range(1, N + 2):
            f[i] = f[i - 1] * i % MOD
        def comb(a, b):
            if b < 0 or b > a or a < 0:
                return 0
            return f[a] * pow(f[b] * f[a - b] % MOD, MOD - 2, MOD) % MOD
        def c3(x):
            return x * (x - 1) * (x - 2) // 6 if x >= 3 else 0
        row = c3(m + 1) * n * n
        col = c3(n + 1) * m * m
        return (row + col) % MOD * comb(N - 2, k - 2) % MOD

