class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        full = (1 << k) - 1
        w = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k) % k)
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        F = [0] * (m + 1)
        F[m] = 1
        for i in range(m - 1, -1, -1):
            cur = 0
            mask = F[i + 1]
            lo = 0 if i > 0 else 1
            for d in range(lo, 10):
                c = (d * w[i]) % k
                cur |= ((mask << c) | (mask >> (k - c))) & full
            F[i] = cur
        digits = []
        acc = 0
        for i in range(m):
            lo = 0 if i > 0 else 1
            chosen = None
            for d in range(9, lo - 1, -1):
                t = (acc + d * w[i]) % k
                if (F[i + 1] >> ((-t) % k)) & 1:
                    chosen = d
                    acc = t
                    break
            if chosen is None:
                return ""
            digits.append(chosen)
        half = ''.join(map(str, digits))
        if n % 2 == 0:
            return half + half[::-1]
        return half + half[-2::-1]

