class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        INF = 1 << 60
        best = 2 * n + 5
        for f in range(1, n + 1):
            states = {0: 0}
            for i in range(26):
                c = cnt[i]
                new = {}
                last = (i == 25)
                for k, v in states.items():
                    t = c + k
                    if t >= f:
                        cost = v + t - f
                        car = t - f
                    else:
                        cost = v + f - t
                        car = 0
                    if last:
                        if cost < new.get(0, INF):
                            new[0] = cost
                    else:
                        if car > f:
                            cost += car - f
                            car = f
                        if cost < new.get(car, INF):
                            new[car] = cost
                    # final frequency 0 for this letter
                    cc = v + t
                    if last:
                        if cc < new.get(0, INF):
                            new[0] = cc
                    else:
                        car2 = t
                        if car2 > f:
                            cc += car2 - f
                            car2 = f
                        if cc < new.get(car2, INF):
                            new[car2] = cc
                states = new
            if 0 in states:
                best = min(best, states[0])
        return best

