import re, bisect

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        def occ(t):
            return [m.start() for m in re.finditer('(?=' + re.escape(t) + ')', s)]
        A = occ(a)
        B = occ(b)
        C = occ(c)
        if not A or not B or not C:
            return -1
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for i in A:
            k_idx = bisect.bisect_left(B, i + la)
            if k_idx == len(B):
                break
            k = B[k_idx]
            m_idx = bisect.bisect_left(C, k + lb)
            if m_idx == len(C):
                continue
            m = C[m_idx]
            L = m + lc - i
            if best == -1 or L < best:
                best = L
        return best

