import sys
import numpy as np
def main():
    data = sys.stdin.read().split()
    n, W = int(data[0]), int(data[1])
    groups = {}
    for i in range(n):
        w = int(data[2 + 2*i]); v = int(data[3 + 2*i])
        groups.setdefault(w, []).append(v)
    dp = np.zeros(W + 1, dtype=np.int64)
    for w, vs in groups.items():
        K = W // w
        if K == 0:
            continue
        ks = np.arange(1, K + 1, dtype=np.int64)
        arrs = [v - 2 * ks + 1 for v in vs]
        allv = np.concatenate(arrs)
        allv = allv[allv > 0]
        if allv.size == 0:
            continue
        if allv.size > K:
            allv = np.partition(allv, allv.size - K)[allv.size - K:]
        allv = np.sort(allv)[::-1]
        for val in allv.tolist():
            if val <= 0:
                break
            dp[w:] = np.maximum(dp[w:], dp[:W + 1 - w] + val)
    print(int(dp[W]))
main()

