class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        P = [0]*(n+1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]
        INF = float('inf')
        mn = [INF]*k
        best = -INF
        for i in range(k, n+1):
            j = i-k
            r = j % k
            if P[j] < mn[r]:
                mn[r] = P[j]
            v = P[i] - mn[i % k]
            if v > best:
                best = v
        return best

