import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        is_p = [True] * LIM
        is_p[0] = is_p[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if is_p[i]:
                for j in range(i * i, LIM, i):
                    is_p[j] = False
        if is_p[n] or is_p[m]:
            return -1
        L = len(str(n))
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist.get(u, float('inf')):
                continue
            if u == m:
                return d
            s = str(u).zfill(L)
            for i in range(L):
                dig = int(s[i])
                for nd in (dig + 1, dig - 1):
                    if 0 <= nd <= 9:
                        t = s[:i] + str(nd) + s[i + 1:]
                        v = int(t)
                        if is_p[v]:
                            continue
                        nd_cost = d + v
                        if nd_cost < dist.get(v, float('inf')):
                            dist[v] = nd_cost
                            heapq.heappush(heap, (nd_cost, v))
        return -1

