        best[0] = 0
        pq = [(0, 0)]
        while pq:
            d, v = heapq.heappop(pq)
            if d > best[v]:
                continue
            for u, w in radj[v]:
                nd = max(d, w)
                if nd < best[u]:
                    best[u] = nd
