class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        S = set(map(tuple, points))
        n = len(points)
        best = -1
        for i in range(n):
            x1, y1 = points[i]
            for j in range(n):
                x2, y2 = points[j]
                if not (x1 < x2 and y1 < y2):
                    continue
                if (x1, y2) not in S or (x2, y1) not in S:
                    continue
                ok = True
                for px, py in points:
                    if x1 <= px <= x2 and y1 <= py <= y2:
                        if (px, py) in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
                            continue
                        ok = False
                        break
                if ok:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

